let globalIndex = 0;
export const ALL_WORDS = [];

RAW_PARTS.forEach(part => {
  part.questions.forEach(q => {
    ALL_WORDS.push({
      index: globalIndex++,
      word: q.word,
      meaning: q.options[q.answer],
      explanation: q.explanation,
      bengali: q.bengali || "অর্থ লোড হচ্ছে...",
      pos: q.pos || "n/a",
      synonyms: q.synonyms || [],
      antonyms: q.antonyms || [],
      example: q.example || "উদাহরণ তৈরি করা হচ্ছে...",
      options: q.options,
      answer: q.answer,
      part: part.part,
      difficulty: part.part === 'A' ? 'foundation' : part.part === 'B' ? 'advanced' : 'exam-level',
      level: Math.floor((globalIndex - 1) / WORDS_PER_LEVEL) + 1
    });
  });
});

export const WORDS_BY_STR = ALL_WORDS.reduce((acc, w) => {
  acc[w.word] = w;
  return acc;
}, {});

export const WORD_COUNT = ALL_WORDS.length;

export const LEVELS = Array.from({ length: TOTAL_LEVELS }, (_, i) => ({
  number: i + 1,
  title: `Level ${i + 1}`,
  wordIndices: Array.from({ length: WORDS_PER_LEVEL }, (_, j) => i * WORDS_PER_LEVEL + j),
  difficulty: i < 5 ? 'foundation' : i < 10 ? 'advanced' : 'exam-level'
}));
